const today = new Date();
const results = [];

for (const item of $input.all()) {
  const row = item.json;

  // Skip paid or cancelled invoices
  if (!row.DueDate || row.Status === 'Paid' || row.Status === 'Cancelled') continue;

  const dueDate = new Date(row.DueDate);
  const diffTime = dueDate - today;
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  let reminderType = null;

  if (diffDays === 7) reminderType = '7-day';
  else if (diffDays === 3) reminderType = '3-day';
  else if (diffDays === 1) reminderType = '1-day';
  else if (diffDays === 0) reminderType = 'due-today';
  else if (diffDays === -1) reminderType = '1-day-overdue';
  else if (diffDays === -7) reminderType = '7-day-overdue';
  else if (diffDays === -14) reminderType = '14-day-overdue';

  if (reminderType) {
    results.push({
      json: {
        ...row,
        daysUntilDue: diffDays,
        reminderType,
        isOverdue: diffDays < 0,
        formattedDueDate: dueDate.toLocaleDateString('en-KE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
      }
    });
  }
}

return results;
